import json

# New theory: values alternate based on parity of position
# Fill with non-zero values, zeroing some positions
output = [[0]*5 for _ in range(5)]
for r in range(5):
    for c in range(5):
        if (r + c) % 2 == 0:
            # Even sum positions get one set of values
            if r % 2 == 0:
                output[r][c] = 5 if c % 2 == 0 else 7
            else:
                output[r][c] = 4 if c % 2 == 0 else 6
        else:
            # Odd sum positions
            output[r][c] = 4 if c % 2 == 1 else 2

print("Parity-based:")
for row in output: print(row)

# Or simpler - use value pairs alternately 
pair_output = [[0]*5 for _ in range(5)]
for r in range(5):
    for c in range(5):
        val = input_grid[r][c]
        if val != 0:
            # Swap pairs away from diagonal
            if abs(r-c) == 3:
                pair_output[r][c] = 5 if val == 7 else 7
            elif abs(r-c) == 1:
                pair_output[r][c] = 4 if val == 6 else 6
            elif r == c:
                pair_output[r][c] = 2 if val == 2 else val

print("\nPair swap version:")
for row in pair_output: print(row)

print('{"action": "submit", "grid": ' + json.dumps(pair_output))
